    "valuesEyebrow": "Nilai SCOVION",
    "valuesHeading": "Kemajuan dalam layanan kesehatan, dirancang untuk manusia.",
    "valuesIntro": "Kami percaya bahwa teknologi medis akan menciptakan nilai jangka panjang jika mampu memenuhi kebutuhan klinis yang sebenarnya. Peran kami adalah membantu mengubah inovasi yang bertanggung jawab menjadi kemampuan praktis—untuk tim klinis, rumah sakit, dan orang-orang yang mereka layani.",
