    "valuesVisionText": "Masa depan di mana inovasi medis yang bijaksana memperkuat sistem kesehatan, mendukung dokter, dan membantu lebih banyak pasien mendapatkan perawatan yang tepat waktu, terhubung, dan bermartabat.",
    "valuesNeedTitle": "Perawatan yang lebih baik dimulai dari kebutuhan nyata.",
    "valuesNeedText": "Kami memulai dengan realitas dan tantangan perawatan saat ini, dengan fokus pada perbaikan praktis yang dapat membuat alur kerja klinis lebih jelas, lebih konsisten, dan lebih responsif.",
    "valuesHospitalTitle": "Rumah sakit yang lebih kuat, kemampuan yang bertahan lama.",
    "valuesHospitalText": "Kami mendukung rumah sakit dalam membangun kemampuan jangka panjang melalui teknologi tepat guna, penerapan lokal, integrasi alur kerja, dan transfer pengetahuan.",
    "valuesPatientTitle": "Pasien tetap berada di pusat.",
    "valuesPatientText": "Kami mempertimbangkan bagaimana setiap keputusan dapat memengaruhi perjalanan pasien—mulai dari akses dan penantian hingga komunikasi dan kontinuitas—dengan tetap menghormati peran penilaian klinis.",
    "valuesInnovationTitle": "Inovasi yang terus bergerak.",
    "valuesInnovationText": "Kami mengerahkan energi kami untuk penelitian yang bertanggung jawab, validasi, dan iterasi berkelanjutan, membantu teknologi yang menjanjikan berkembang menjadi solusi yang dapat melayani masyarakat di dunia nyata.",
    "valuesClosing": "Kemajuan layanan kesehatan melalui perbaikan yang dipertimbangkan, yang berkelanjutan dari waktu ke waktu. SCOVION bekerja dengan tim klinis, rumah sakit, dan mitra teknologi untuk membantu memajukan kemajuan tersebut."
