    "partnerMarketFitTitle": "Clinical at market fit",
    "partnerMarketFitText": "Sinusuri namin ang nilalayon na paggamit, mga target na gumagamit, mga landas ng pangangalaga, mga pangangailangan ng ebidensya at mga kinakailangan sa lokalisasyon bago magrekomenda ng praktikal na direksyon.",
