    "partnerClinicalLinksTitle": "Klinikal at koneksyon sa kasosyo",
    "partnerClinicalLinksText": "Pinapadali namin ang mga nakatutok na talakayan sa mga ospital, clinician, at mga stakeholder ng pagpapatupad upang maunawaan ang produkto, daloy ng trabaho at akma ng serbisyo.",
    "partnerDeploymentTitle": "Lokal na deployment at pagsasanay",
    "partnerDeploymentText": "Inuugnay namin ang pagpaplano ng pagpapatupad, paghahanda sa daloy ng trabaho, online o on-site na pagsasanay at patuloy na suporta sa pagpapatakbo ayon sa saklaw ng bawat proyekto.",
    "partnerPrinciple": "Ang bawat pakikipagtulungan ay hinuhubog sa klinikal na halaga, naaangkop na regulasyon, kahandaan sa produkto at mga pangangailangan ng mga lokal na pangkat ng pangangalaga sa kalusugan.",
    "deploymentEyebrow": "Pag-deploy sa lugar",
    "deploymentHeading": "AI na gumagana sa loob ng ospital.",
    "deploymentIntro": "Sinusuportahan ng SCOVION ang on-premises deployment, na may AI inference na ginawa sa computing resources sa loob ng ospital. Maaaring manatili ang data ng pasyente at klinikal sa kontroladong kapaligiran ng institusyon habang ang mga team ay nagpapanatili ng tumutugon na access sa mga resultang tinulungan ng AI.",
    "deploymentBoundary": "kapaligirang kontrolado ng ospital",
