    "deploymentOutputLabel": "Mga resulta para sa klinikal na pagsusuri",
    "deploymentPrivacyLine": "Para sa mga naka-configure na on-premise na daloy ng trabaho, ang AI inference ay isinasagawa nang lokal at ang data ng pasyente at klinikal ay nananatili sa loob ng kapaligiran ng ospital.",
    "deploymentBenefitLocalTitle": "Lokal ayon sa disenyo",
    "deploymentBenefitLocalText": "Ang AI inference ay tumatakbo sa mga mapagkukunan ng computing na nakabatay sa ospital, na binabawasan ang pag-asa sa panlabas na pagproseso ng ulap.",
    "deploymentBenefitGovernanceTitle": "Data sa ilalim ng pamamahala ng ospital",
    "deploymentBenefitGovernanceText": "Maaaring sundin ng pangangasiwa ng data ang sariling pag-access, pagpapanatili at mga patakaran sa seguridad ng ospital sa loob ng kontroladong kapaligiran nito.",
    "deploymentBenefitLatencyTitle": "Tumutugon sa punto ng pangangalaga",
    "deploymentBenefitLatencyText": "Maaaring bawasan ng lokal na pagproseso ang mga round trip sa network at suportahan ang mababang latency na access sa mga resultang tinulungan ng AI.",
    "deploymentBenefitContinuityTitle": "Pagpapatuloy sa paligid ng mga lokal na operasyon",
    "deploymentBenefitContinuityText": "Maaaring manatiling available ang mga pangunahing inference workflow sa panahon ng mga pagkaantala sa panlabas na network, napapailalim sa pagkakaroon ng lokal na imprastraktura.",
    "deploymentBenefitIntegrationTitle": "Nakaplano para sa kasalukuyang kapaligiran",
    "deploymentBenefitIntegrationText": "Ang deployment ay pinaplano sa paligid ng kasalukuyang imaging at mga sistema ng impormasyon, na may lokal na pagsasaayos, pagpapatunay at pagsasanay ng koponan.",
    "deploymentNote": "Ang saklaw ng deployment at compatibility ng system ay tinatasa para sa bawat ospital.",
    "deploymentCta": "Talakayin ang lokal na deployment",
    "mdaFrameworkDesc": "Balangkas ng pagpaparehistro ng medikal na device ng Malaysia sa ilalim ng Medical Device Act 2012 (Act 737), na pinangangasiwaan ng Medical Device Authority sa ilalim ng Ministry of Health Malaysia.",
    "pmdaFrameworkDesc": "Sa ilalim ng balangkas ng PMD Act ng Japan, ang PMDA ay nagsasagawa ng mga siyentipikong pagsusuri sa produkto at mga aktibidad sa kaligtasan pagkatapos ng merkado, habang ang Ministry of Health, Labor at Welfare ay gumagawa ng mga naaangkop na desisyon sa pag-apruba.",
    "valuesEyebrow": "Mga Halaga ng SCOVION",
    "valuesHeading": "Pag-unlad sa pangangalagang pangkalusugan, na idinisenyo sa paligid ng mga tao.",
    "valuesIntro": "Naniniwala kami na ang medikal na teknolohiya ay lumilikha ng pangmatagalang halaga kapag ito ay tumutugon sa mga tunay na klinikal na pangangailangan. Ang aming tungkulin ay tumulong na gawing praktikal na kakayahan ang responsableng pagbabago—para sa mga klinikal na koponan, ospital at mga taong pinaglilingkuran nila.",
    "valuesVisionLabel": "Ang aming paningin",
    "valuesVisionText": "Isang kinabukasan kung saan ang maalalahanin na medikal na inobasyon ay nagpapalakas ng mga sistema ng kalusugan, sumusuporta sa mga clinician at tumutulong sa mas maraming pasyente na makaranas ng napapanahong, konektado at marangal na pangangalaga.",
    "valuesNeedTitle": "Ang mas mabuting pangangalaga ay nagsisimula sa mga tunay na pangangailangan.",
    "valuesNeedText": "Nagsisimula kami sa mga katotohanan at hamon ng pangangalaga ngayon, na tumutuon sa mga praktikal na pagpapabuti na maaaring gawing mas malinaw, mas pare-pareho at mas tumutugon ang mga klinikal na daloy ng trabaho.",
    "valuesHospitalTitle": "Mas matibay na ospital, pangmatagalang kakayahan.",
    "valuesHospitalText": "Sinusuportahan namin ang mga ospital sa pagbuo ng pangmatagalang kakayahan sa pamamagitan ng naaangkop na teknolohiya, lokal na pagpapatupad, pagsasama ng daloy ng trabaho at paglilipat ng kaalaman.",
    "valuesPatientTitle": "Ang mga pasyente ay nananatili sa sentro.",
    "valuesPatientText": "Isinasaalang-alang namin kung paano maaaring makaapekto ang bawat desisyon sa paglalakbay ng pasyente—mula sa pag-access at paghihintay hanggang sa komunikasyon at pagpapatuloy—habang iginagalang ang papel ng klinikal na paghatol.",
    "valuesInnovationTitle": "Innovation na patuloy na gumagalaw.",
    "valuesInnovationText": "Iniaalay namin ang aming lakas sa responsableng pagsasaliksik, pagpapatunay at patuloy na pag-ulit, na tumutulong sa mga promising na teknolohiya na maging mga solusyon na maaaring magsilbi sa mga tao sa totoong mundo.",
    "valuesClosing": "Sumusulong ang pangangalagang pangkalusugan sa pamamagitan ng itinuturing na mga pagpapabuti, na pinananatili sa paglipas ng panahon. Nakikipagtulungan ang SCOVION sa mga klinikal na koponan, ospital at mga kasosyo sa teknolohiya upang tumulong sa pagsulong na iyon."
