    "medicalText": "ການວິເຄາະພາບລວມທີ່ເນັ້ນໃສ່, ການວາງແຜນການຜ່າຕັດ 3D, ອຸປະກອນອັດສະລິຍະ, ໂຮງໝໍ AI ແລະເທັກໂນໂລຍີຊ່ວຍເຫຼືອ.",
    "medNote": "ຄວາມພ້ອມຂອງຜະລິດຕະພັນ, ຕົວຊີ້ບອກ ແລະ ສະຖານະລະບຽບການແມ່ນແຕກຕ່າງກັນໄປຕາມຕະຫຼາດ. ກະລຸນາຕິດຕໍ່ SCOVION ສໍາລັບຂໍ້ມູນທ້ອງຖິ່ນ.",
    "read": "ການກວດ ແລະວິນິດໄສ",
