    "scholarText": "InferScholar® ແລະ InferMatrix ສະຫນັບສະຫນູນໂຮງຫມໍແລະນັກຄົ້ນຄວ້າໃນການຄົ້ນຄວ້າແລະຄໍາຮ້ອງສະຫມັກທີ່ເປີດໃຊ້ AI.",
    "agriTitle": "AI ການກະເສດສຳລັບທຸກໆການຕັດສິນໃຈທີ່ເຕີບໃຫຍ່.",
    "agriText2": "ຫັນສັນຍານພາກສະໜາມໄປສູ່ການກະທຳທີ່ທັນເວລາ, ສາມາດຂະຫຍາຍໄດ້—ຈາກການເບິ່ງເຫັນການປູກພືດ ແລະ ການເພີ່ມປະສິດທິພາບຂອງຊັບພະຍາກອນໄປສູ່ການວາງແຜນການດຳເນີນງານ.",
    "agentTitle": "AI Agent ສຳລັບການເຮັດວຽກທີ່ດີຂຶ້ນ ບໍ່ແມ່ນເພີ່ມວຽກ.",
