    "aboutTitle": "ພວກເຮົາເຮັດໃຫ້ AI ປະຕິບັດໄດ້.",
    "aboutText": "SCOVION ແມ່ນບໍລິສັດ AI ທີ່ໃຊ້ໄດ້ສຸມໃສ່ການເຊື່ອມຕໍ່ເຕັກໂນໂລຊີລະດັບໂລກກັບຄວາມຊ່ຽວຊານໃນທ້ອງຖິ່ນທີ່ຕ້ອງການເພື່ອເຮັດໃຫ້ມັນເປັນປະໂຫຍດ. ພວກເຮົາເຮັດວຽກກັບອົງການຈັດຕັ້ງທີ່ຊອກຫາຄວາມຄືບຫນ້າທີ່ສາມາດວັດແທກໄດ້, ບໍ່ແມ່ນໂຮງລະຄອນ AI.",
