    "trafficLabel": "ວິໄສທັດຄອມພິວເຕີຢູ່ຂອບ",
    "trafficTitle": "ປ້າຍທະບຽນຈະລາຈອນຕາມທ້ອງຖະໜົນ",
    "trafficDesc": "ທໍ່ວິໄສທັດສາມາດກວດຫາຍານພາຫະນະ, ຊອກຫາປ້າຍກຳກັບ, ຮັບຮູ້ຕົວລະຄອນ ແລະເຊື່ອມຕໍ່ຜົນໄດ້ຮັບກັບລະບົບທີ່ໄດ້ຮັບອະນຸຍາດ. ຕົວແບບສາມາດປັບໄດ້ສໍາລັບຮູບແບບແຜ່ນທ້ອງຖິ່ນ, ຕໍາແຫນ່ງກ້ອງຖ່າຍຮູບ, ແສງສະຫວ່າງແລະສະພາບອາກາດ, ສະຫນັບສະຫນູນບ່ອນຈອດລົດ, ການຂົນສົ່ງ, ການຄວບຄຸມການເຂົ້າເຖິງແລະການຄຸ້ມຄອງເສັ້ນທາງ.",
    "trafficPoint1": "ການກວດຫາຍານພາຫະນະ, ການຕິດຕາມ ແລະ ການຕັ້ງແຜ່ນ",
    "trafficPoint2": "OCR ປັບແຕ່ງຮູບແບບທ້ອງຖິ່ນ ແລະເງື່ອນໄຂການໃຊ້ງານ",
    "trafficPoint3": "ຂອບ ຫຼື ການນຳໃຊ້ສ່ວນຕົວດ້ວຍການເກັບຮັກສາຂໍ້ມູນທີ່ສາມາດກຳນົດຄ່າໄດ້",
