    "partnersIntro": "SCOVION ເຮັດວຽກກັບອົງການຈັດຕັ້ງເຕັກໂນໂລຢີການດູແລສຸຂະພາບເພື່ອຊ່ວຍໃຫ້ວິທີແກ້ໄຂທີ່ກ່ຽວຂ້ອງທາງດ້ານຄລີນິກກ້າວຫນ້າຢ່າງມີຄວາມຮັບຜິດຊອບໃນທົ່ວຕະຫຼາດ, ໂດຍເອົາໃຈໃສ່ຢ່າງລະມັດລະວັງຕໍ່ຄວາມຕ້ອງການຂອງທ້ອງຖິ່ນ, ຄວາມພ້ອມດ້ານກົດລະບຽບແລະການຈັດຕັ້ງປະຕິບັດຕົວຈິງ.",
    "homePartnersHeading": "ຄວາມຄືບໜ້າຂອງການດູແລສຸຂະພາບແມ່ນສ້າງຂຶ້ນຮ່ວມກັນ.",
    "homePartnersText": "ພວກເຮົາເຮັດວຽກຮ່ວມກັບຄູ່ຮ່ວມງານທີ່ເນັ້ນໃສ່ການດູແລສຸຂະພາບເພື່ອຊ່ວຍໃຫ້ເຕັກໂນໂລຢີການແພດເຄື່ອນຍ້າຍຢ່າງມີຄວາມຮັບຜິດຊອບລະຫວ່າງຈີນ, ອາຊີຕາເວັນອອກສຽງໃຕ້ແລະຕະຫຼາດສາກົນ.",
