    "customSolutionsFooter": "Custom AI ບໍລິການ",
    "contactServicesEyebrow": "ການຈັດຕັ້ງປະຕິບັດ ແລະ ການຮັບຮອງເອົາ",
    "contactServicesTitle": "ສະໜັບສະໜູນທີມແພດ",
