    "partnersIntro": "SCOVION သည် ဒေသဆိုင်ရာလိုအပ်ချက်များ၊ စည်းမျဥ်းစည်းကမ်းဆိုင်ရာ အဆင်သင့်ဖြစ်မှုနှင့် လက်တွေ့ကမ္ဘာတွင် လက်တွေ့အကောင်အထည်ဖော်မှုတို့ဖြင့် စျေးကွက်များတစ်လျှောက်တွင် သက်ဆိုင်သည့်ဖြေရှင်းချက်များအား တာဝန်သိစွာလုပ်ဆောင်နိုင်ရန် ကျန်းမာရေးစောင့်ရှောက်မှုနည်းပညာအဖွဲ့အစည်းများနှင့် လက်တွဲလုပ်ဆောင်ပါသည်။",
    "homePartnersHeading": "ကျန်းမာရေးစောင့်ရှောက်မှုတိုးတက်မှုကို အတူတကွတည်ဆောက်သည်။",
    "homePartnersText": "ကျွန်ုပ်တို့သည် တရုတ်၊ အရှေ့တောင်အာရှနှင့် နိုင်ငံတကာစျေးကွက်များကြားတွင် ဆေးဘက်ဆိုင်ရာနည်းပညာများကို တာဝန်သိစွာ ရွေ့လျားနိုင်ရန် ကူညီပေးရန်အတွက် ကျန်းမာရေးစောင့်ရှောက်မှုဆိုင်ရာ မိတ်ဖက်များနှင့် လက်တွဲဆောင်ရွက်ပါသည်။",
    "partnerOrganisation": "မိတ်ဖက်အဖွဲ့အစည်း",
    "partnerOrganisationText": "SCOVION ၏ ကျန်းမာရေးစောင့်ရှောက်မှု ပူးပေါင်းဆောင်ရွက်မှုကွန်ရက်ရှိ မိတ်ဖက်အဖွဲ့အစည်းတစ်ခုသည် ရွေးချယ်ထားသော နယ်စပ်ဖြတ်ကျော် ဆေးဘက်ဆိုင်ရာနည်းပညာဆိုင်ရာ အခွင့်အလမ်းများအတွက် ကျွန်ုပ်တို့နှင့် လက်တွဲဆောင်ရွက်ပါသည်။",
    "meetPartners": "ကျွန်ုပ်တို့၏လုပ်ဖော်ကိုင်ဖက်များ → တွေ့ဆုံပါ။",
