    "contactServicesEyebrow": "အကောင်အထည်ဖော်ခြင်းနှင့် မွေးစားခြင်း။",
    "contactServicesTitle": "ဆေးခန်းအဖွဲ့များကို ပံ့ပိုးကူညီပါ။",
    "contactServicesText": "ဒေသတွင်း ဖြန့်ကျက်ချထားရေး၊ အလုပ်အသွားအလာ ပြင်ဆင်မှု၊ အွန်လိုင်း သို့မဟုတ် ဆိုက်တွင်း လေ့ကျင့်ရေး နှင့် လက်ရှိလုပ်ငန်းဆောင်ရွက်မှုဆိုင်ရာ ပံ့ပိုးကူညီမှုများကို ဆွေးနွေးပါ။",
    "partnerRouteChinaSeaLabel": "တရုတ် → အရှေ့တောင်အာရှ",
    "partnerRouteChinaSeaTitle": "တရုတ်ဆေးဘက်ဆိုင်ရာနည်းပညာကို အရှေ့တောင်အာရှ စောင့်ရှောက်မှုအဖွဲ့များနှင့် ပိုမိုနီးကပ်စေခြင်း။",
    "partnerRouteChinaSeaText": "ရွေးချယ်ထားသော ဆေးဘက်ဆိုင်ရာနည်းပညာများအတွက်၊ ကျွန်ုပ်တို့သည် ဒေသဆိုင်ရာ ဆေးခန်းလိုအပ်ချက်များနှင့် စျေးကွက်ကိုက်ညီမှု၊ မြေပုံစည်းမျဉ်းနှင့် ဒေသသတ်မှတ်မှုလမ်းကြောင်းများကို အကဲဖြတ်ရန်၊ သက်ဆိုင်ရာ ကျန်းမာရေးစောင့်ရှောက်မှုဆိုင်ရာ သက်ဆိုင်သူများကို ချိတ်ဆက်ကာ အသုံးချမှုနှင့် လေ့ကျင့်ရေးတို့ကို ပံ့ပိုးကူညီပေးပါသည်။",
    "partnerRouteGlobalChinaLabel": "နိုင်ငံတကာဈေးကွက်များ → တရုတ်",
