    "partnerRouteGlobalChinaText": "ကျွန်ုပ်တို့သည် သင့်လျော်သော စျေးကွက်ဝင်ရောက်မှုချဉ်းကပ်မှုအား မသတ်မှတ်မီတွင် လက်တွေ့ဆက်စပ်မှု၊ စျေးကွက်နှင့် စည်းမျဉ်းစည်းကမ်းဆိုင်ရာ အဆင်သင့်ဖြစ်မှု၊ ဒေသဆိုင်ရာလိုအပ်ချက်များနှင့် အလားအလာရှိသော အကောင်အထည်ဖော်ဖော်များကို နားလည်ရန် ကျွန်ုပ်တို့သည် နည်းပညာပိုင်ရှင်များနှင့် လက်တွဲလုပ်ဆောင်ပါသည်။",
    "partnerSupportEyebrow": "SCOVION သည် ပူးပေါင်းဆောင်ရွက်မှုကို မည်သို့ပံ့ပိုးမည်နည်း။",
    "partnerSupportHeading": "စျေးကွက်နားလည်မှုမှ ဒေသခံမွေးစားခြင်းအထိ။",
    "partnerMarketFitTitle": "ဆေးခန်းနှင့် စျေးကွက် အံကိုက်",
    "partnerMarketFitText": "ကျွန်ုပ်တို့သည် ရည်ရွယ်ထားသောအသုံးပြုမှု၊ ပစ်မှတ်အသုံးပြုသူများ၊ စောင့်ရှောက်မှုလမ်းကြောင်းများ၊ အထောက်အထားလိုအပ်ချက်များနှင့် လက်တွေ့ကျသောဦးတည်ချက်အား အကြံပြုခြင်းမပြုမီ ဆန်းစစ်လေ့လာပါသည်။",
    "partnerRegulatoryTitle": "စည်းကမ်းထိန်းသိမ်းရေး အဆင်သင့်",
    "partnerRegulatoryText": "ကျွန်ုပ်တို့သည် သက်ဆိုင်ရာ ဆေးဘက်ဆိုင်ရာ-စက်ပစ္စည်း လိုအပ်ချက်များကို မြေပုံဆွဲကာ၊ စာရွက်စာတမ်း ကွာဟချက်များအား ရှာဖွေဖော်ထုတ်ကာ သင့်လျော်သည့်နေရာတွင် အရည်အချင်းပြည့်မီသော ဒေသဆိုင်ရာ ကျွမ်းကျင်သူများနှင့် ညှိနှိုင်းဆောင်ရွက်ပေးပါသည်။",
    "partnerClinicalLinksTitle": "ဆေးခန်းနှင့် ပါတနာချိတ်ဆက်မှု",
    "partnerClinicalLinksText": "ကျွန်ုပ်တို့သည် ထုတ်ကုန်၊ လုပ်ငန်းအသွားအလာနှင့် ဝန်ဆောင်မှုနှင့် ကိုက်ညီမှုရှိကြောင်း နားလည်ရန် ဆေးရုံများ၊ ဆေးခန်းများနှင့် အကောင်အထည်ဖော်မှုဆိုင်ရာ သက်ဆိုင်သူများနှင့် အာရုံစိုက်ဆွေးနွေးမှုများကို လွယ်ကူချောမွေ့စေပါသည်။",
    "partnerDeploymentTitle": "ပြည်တွင်း ဖြန့်ကျက်ခြင်းနှင့် လေ့ကျင့်ရေး",
    "partnerDeploymentText": "ကျွန်ုပ်တို့သည် အကောင်အထည်ဖော်မှုအစီအစဉ်ရေးဆွဲခြင်း၊ အလုပ်အသွားအလာပြင်ဆင်ခြင်း၊ အွန်လိုင်း သို့မဟုတ် ဆိုက်တွင်းလေ့ကျင့်ရေးနှင့် ပရောဂျက်တစ်ခုစီ၏ နယ်ပယ်အလိုက် လုပ်ငန်းဆောင်ရွက်မှုဆိုင်ရာ ပံ့ပိုးကူညီမှုများကို ညှိနှိုင်းဆောင်ရွက်ပေးပါသည်။",
    "partnerPrinciple": "ပူးပေါင်းဆောင်ရွက်မှုတိုင်းသည် ဆေးခန်းတန်ဖိုး၊ အသုံးချနိုင်သော စည်းမျဉ်းများ၊ ထုတ်ကုန်အဆင်သင့်နှင့် ဒေသတွင်း ကျန်းမာရေးစောင့်ရှောက်မှုအဖွဲ့များ၏ လိုအပ်ချက်များကို ပုံဖော်ထားသည်။",
    "deploymentEyebrow": "အိမ်တွင်းဖြန့်ကျက်မှု",
    "deploymentHeading": "AI ဆေးရုံအတွင်းအလုပ်လုပ်သည်။",
    "deploymentIntro": "SCOVION သည် ဆေးရုံအတွင်း တွက်ချက်ခြင်းဆိုင်ရာ အရင်းအမြစ်များအပေါ် AI အနုမာနဖြင့် လုပ်ဆောင်ခြင်းဖြင့် ပရိဝုဏ်အတွင်း ဖြန့်ကျက်မှုကို ပံ့ပိုးပေးပါသည်။ အဖွဲ့များသည် AI-အကူအညီရလဒ်များကို တုံ့ပြန်ဝင်ရောက်ခွင့်ကို ဆက်လက်ထိန်းသိမ်းထားချိန်တွင် လူနာနှင့် ဆေးခန်းဒေတာများသည် အဖွဲ့အစည်း၏ထိန်းချုပ်ထားသောပတ်ဝန်းကျင်တွင် ရှိနေနိုင်သည်။",
    "deploymentBoundary": "ဆေးရုံထိန်းချုပ်ထားသောပတ်ဝန်းကျင်",
    "deploymentDataLabel": "ပုံရိပ်ဖော်ခြင်းနှင့် လက်တွေ့ဒေတာ",
