    "deploymentPrivacyLine": "စီစဉ်သတ်မှတ်ထားသော လုပ်ငန်းခွင်အတွင်းတွင်၊ AI ကောက်ချက်ကို ပြည်တွင်း၌ လုပ်ဆောင်ပြီး လူနာနှင့် ဆေးခန်းဆိုင်ရာ အချက်အလက်များသည် ဆေးရုံပတ်ဝန်းကျင်တွင် ကျန်ရှိနေပါသည်။",
    "deploymentBenefitLocalTitle": "ဒေသအလိုက် ဒီဇိုင်း",
