    "deploymentBenefitGovernanceText": "ဒေတာကိုင်တွယ်ခြင်းသည် ဆေးရုံ၏ကိုယ်ပိုင်ဝင်ရောက်ခွင့်၊ ထိန်းသိမ်းမှုနှင့် လုံခြုံရေးမူဝါဒများကို ၎င်း၏ထိန်းချုပ်ထားသောပတ်ဝန်းကျင်အတွင်းတွင် လိုက်နာနိုင်သည်။",
    "deploymentBenefitLatencyTitle": "ဂရုစိုက်သည့်နေရာတွင် တုံ့ပြန်သည်။",
    "deploymentBenefitLatencyText": "Local processing သည် ကွန်ရက်အသွားအပြန်ခရီးများကို လျှော့ချနိုင်ပြီး AI-အကူအညီရလဒ်များဆီသို့ latency နည်းပါးသောဝင်ရောက်ခွင့်ကို ပံ့ပိုးပေးပါသည်။",
    "deploymentBenefitContinuityTitle": "ပြည်တွင်းလုပ်ငန်းဆောင်ရွက်မှုများ ဆက်တိုက်လုပ်ဆောင်ခြင်း။",
